bg=1
patterns={3:[[1,0,1],[1,0,1],[1,1,1]],9:[[0,0,1],[0,1,1],[1,0,1]],8:[[1,1,1],[0,1,0],[1,1,1]]}
# pattern lists indicate bg input (color main 0); output interior invert = main color at input bg locations, bg at input main locations
out=[[1]*7 for _ in range(19)]
for start,col in [(1,3),(7,9),(13,8)]:
    for r in range(5):
        for c in range(5): out[start+r][1+c]=col
    for r in range(3):
        for c in range(3): out[start+1+r][2+c]=1 if patterns[col][r][c] else col
print(out)
